CREATE     PROCEDURE [synapse_fo].[usp_Update_GENERALJOURNALACCOUNTENTRY]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:42
	Description: Update stored procedure for GENERALJOURNALACCOUNTENTRY from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ACCOUNTINGCURRENCYAMOUNT] = stg.[ACCOUNTINGCURRENCYAMOUNT],
		tgt.[ALLOCATIONLEVEL] = stg.[ALLOCATIONLEVEL],
		tgt.[ASSETLEASEPOSTINGTYPES] = stg.[ASSETLEASEPOSTINGTYPES],
		tgt.[ASSETLEASETRANSACTIONTYPE] = stg.[ASSETLEASETRANSACTIONTYPE],
		tgt.[CREATEDTRANSACTIONID] = stg.[CREATEDTRANSACTIONID],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		--tgt.[FileName] = stg.[FileName],
		tgt.[FINTAG] = stg.[FINTAG],
		tgt.[GENERALJOURNALENTRY] = stg.[GENERALJOURNALENTRY],
		tgt.[HISTORICALEXCHANGERATEDATE] = stg.[HISTORICALEXCHANGERATEDATE],
		tgt.[ISCORRECTION] = stg.[ISCORRECTION],
		tgt.[ISCREDIT] = stg.[ISCREDIT],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		tgt.[LEDGERACCOUNT] = stg.[LEDGERACCOUNT],
		tgt.[LEDGERDIMENSION] = stg.[LEDGERDIMENSION],
		--tgt.[LSN] = stg.[LSN],
		tgt.[MAINACCOUNT] = stg.[MAINACCOUNT],
		tgt.[ORIGINALACCOUNTENTRY] = stg.[ORIGINALACCOUNTENTRY],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[PAYMENTREFERENCE] = stg.[PAYMENTREFERENCE],
		tgt.[POSTINGTYPE] = stg.[POSTINGTYPE],
		tgt.[PROJID_SA] = stg.[PROJID_SA],
		tgt.[PROJTABLEDATAAREAID] = stg.[PROJTABLEDATAAREAID],
		tgt.[QUANTITY] = stg.[QUANTITY],
		tgt.[REASONREF] = stg.[REASONREF],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[REPORTINGCURRENCYAMOUNT] = stg.[REPORTINGCURRENCYAMOUNT],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TEXT] = stg.[TEXT],
		tgt.[TRANSACTIONCURRENCYAMOUNT] = stg.[TRANSACTIONCURRENCYAMOUNT],
		tgt.[TRANSACTIONCURRENCYCODE] = stg.[TRANSACTIONCURRENCYCODE]
	 FROM [synapse_fo].[GENERALJOURNALACCOUNTENTRY] tgt
		INNER JOIN [staging_fo].[GENERALJOURNALACCOUNTENTRY] stg
			ON  stg.[RECID] = tgt.[RECID] 
		
END
